(()=>{'use strict';const $=s=>document.querySelector(s);const idle=window.requestIdleCallback||((fn)=>setTimeout(fn,80));const files={core:['runtime.js','messenger-actions.js','app-enhancements.js','mobile-id.js'],social:['social-runtime.js'],resources:['sid-runtime.js'],voice:['voice-messages.js']};const loaded=new Set(['state-store.js']);const loading=new Map();function setProgress(n,text){const p=Math.max(0,Math.min(100,n)),bar=$('#awe-progress-bar'),val=$('#awe-progress-value'),label=$('#awe-loader-text');if(bar)bar.style.width=p+'%';if(val)val.textContent=p+'%';if(label)label.textContent=text}function loadOne(src){if(loaded.has(src))return Promise.resolve();if(loading.has(src))return loading.get(src);const promise=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='./'+src;s.async=true;s.onload=()=>{loaded.add(src);resolve()};s.onerror=()=>reject(Error('Failed to load '+src));document.body.appendChild(s)});loading.set(src,promise);return promise}async function loadGroup(name,label){const list=files[name]||[];for(let i=0;i<list.length;i++){setProgress(Math.round(i/list.length*100),label+' '+(i+1)+'/'+list.length);try{await loadOne(list[i])}catch(e){console.error(e)}}setProgress(100,label+' ready')}function hide(){const x=$('#awe-loader');if(!x)return;x.classList.add('ready');setTimeout(()=>x.remove(),180)}async function start(){setProgress(8,'Identity ready');await loadGroup('core','Core');hide();idle(()=>loadGroup('social','Social'),{timeout:2500})}function lazy(){document.addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(!b)return;const v=b.dataset.view;if(v==='channels')loadGroup('social','Channels');if(v==='resources')loadGroup('resources','Resources');if(v==='calls')loadGroup('voice','Calls')},{passive:true});document.addEventListener('click',e=>{if(e.target.closest('#voice-message,#voice,#video,#screen'))loadGroup('voice','Call media')},{passive:true})}addEventListener('DOMContentLoaded',()=>{lazy();idle(()=>start(),{timeout:1200})},{once:true});})();